package net.civeira.phylax.feature.identity.tenantconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantconfig.domain.TenantConfig;
import net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject.DcrAllowedAuthMethodsVO;

class DcrAllowedAuthMethodsValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of dcr allowed auth methods of tenant config")
  void test_dcr_allowed_auth_methods_value_holder_assign_plain_value() {
    Object holder = new Object();
    DcrAllowedAuthMethodsValueHolder<Object> value = new DcrAllowedAuthMethodsValueHolder<>(holder);
    Assertions.assertSame(holder, value.dcrAllowedAuthMethods("one"),
        "Setters must return the holder");
    Assertions.assertTrue(value.getDcrAllowedAuthMethodsValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getDcrAllowedAuthMethods().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.dcrAllowedAuthMethodsNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getDcrAllowedAuthMethodsValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getDcrAllowedAuthMethods().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of dcr allowed auth methods of tenant config")
  void test_dcr_allowed_auth_methods_value_holder_assign_value_object() {
    Object holder = new Object();
    DcrAllowedAuthMethodsValueHolder<Object> value = new DcrAllowedAuthMethodsValueHolder<>(holder);
    DcrAllowedAuthMethodsVO vo = DcrAllowedAuthMethodsVO.from("one");
    Assertions.assertFalse(value.getDcrAllowedAuthMethodsValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.dcrAllowedAuthMethods(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getDcrAllowedAuthMethodsValue().orElseThrow());
    Assertions.assertSame(holder, value.dcrAllowedAuthMethods(Optional.empty()));
    Assertions.assertFalse(value.getDcrAllowedAuthMethodsValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.dcrAllowedAuthMethods(Optional.of(vo)));
    Assertions.assertSame(vo, value.getDcrAllowedAuthMethodsValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of dcr allowed auth methods of tenant config against the original")
  void test_dcr_allowed_auth_methods_value_holder_read() {
    Object holder = new Object();
    DcrAllowedAuthMethodsValueHolder<Object> value = new DcrAllowedAuthMethodsValueHolder<>(holder);
    DcrAllowedAuthMethodsVO vo = DcrAllowedAuthMethodsVO.from("one");
    DcrAllowedAuthMethodsVO other = DcrAllowedAuthMethodsVO.from("one");
    TenantConfig original = Mockito.mock(TenantConfig.class);
    Mockito.when(original.getDcrAllowedAuthMethodsValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readDcrAllowedAuthMethods(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readDcrAllowedAuthMethods(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.dcrAllowedAuthMethods(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readDcrAllowedAuthMethods(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readDcrAllowedAuthMethods(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of dcr allowed auth methods of tenant config")
  void test_dcr_allowed_auth_methods_value_holder_unset() {
    Object holder = new Object();
    DcrAllowedAuthMethodsValueHolder<Object> value = new DcrAllowedAuthMethodsValueHolder<>(holder);
    DcrAllowedAuthMethodsVO vo = DcrAllowedAuthMethodsVO.from("one");
    value.dcrAllowedAuthMethods(vo);
    Assertions.assertSame(holder,
        value.unsetDcrAllowedAuthMethodsIfMatches("dcrAllowedAuthMethods_other"));
    Assertions.assertTrue(value.getDcrAllowedAuthMethodsValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetDcrAllowedAuthMethodsIfMatches("dcrAllowedAuthMethods"));
    Assertions.assertFalse(value.getDcrAllowedAuthMethodsValue().isPresent(),
        "The field name must clear the value");
    value.dcrAllowedAuthMethods(vo);
    Assertions.assertSame(holder, value.unsetDcrAllowedAuthMethods());
    Assertions.assertFalse(value.getDcrAllowedAuthMethodsValue().isPresent(),
        "Unset must clear the value");
  }
}
